/**
 * Exercise stage: one clock drives the 2D illustration, the 3D avatar or the rendered demonstrator clip.
 * Frames are drawn outside Preact's render cycle (direct DOM / WebGL), so
 * the page itself only re-renders a few times per second for the HUD text.
 */
import { useEffect, useRef, useState } from 'preact/hooks';
import type { Exercise } from '../../rehab/exercises';
import { planFor, sceneAt, type MotionOptions, type Plan, type Scene } from '../../rehab/motion';
import { clipFlip, clipFor, clipTime, clipUrl, type DemoClip } from '../../rehab/demoClips';
import { HAND_COLOR, render2D, type View2D } from './face2d';
import type { Face3D } from './face3d';

/** Wall clock with play / pause / seek and playback speed. */
export function useExerciseClock(total: number) {
  const ref = useRef({ running: false, base: 0, offset: 0, speed: 1 });
  const [, setTick] = useState(0);
  const bump = () => setTick((t) => t + 1);
  const get = (): number => {
    const r = ref.current;
    return Math.min(total, r.running ? r.offset + ((performance.now() - r.base) / 1000) * r.speed : r.offset);
  };
  useEffect(() => {
    if (!ref.current.running) return;
    const id = setInterval(() => {
      if (get() >= total) ref.current = { ...ref.current, running: false, offset: total };
      bump();
    }, 200);
    return () => clearInterval(id);
  });
  return {
    get,
    running: ref.current.running,
    speed: ref.current.speed,
    play: () => {
      const off = get() >= total ? 0 : get();
      ref.current = { ...ref.current, running: true, base: performance.now(), offset: off };
      bump();
    },
    pause: () => {
      ref.current = { ...ref.current, running: false, offset: get() };
      bump();
    },
    reset: () => {
      ref.current = { ...ref.current, running: false, offset: 0 };
      bump();
    },
    seek: (sec: number) => {
      ref.current = { ...ref.current, base: performance.now(), offset: Math.max(0, Math.min(total, sec)) };
      bump();
    },
    setSpeed: (speed: number) => {
      ref.current = { ...ref.current, offset: get(), base: performance.now(), speed };
      bump();
    },
  };
}
export type Clock = ReturnType<typeof useExerciseClock>;

let uidSeq = 0;

export interface StageProps {
  ex: Exercise;
  plan: Plan;
  clock: Clock;
  mode: '2d' | '3d' | 'video';
  view: View2D;
  loupe: boolean;
  onFail3D?: () => void;
}

export function RehabStage({ ex, plan, clock, mode, view, loupe, onFail3D }: StageProps) {
  const [uid] = useState(() => `fsr${++uidSeq}`);
  const svgRef = useRef<SVGSVGElement>(null);
  const loupeRef = useRef<SVGSVGElement>(null);
  const box3d = useRef<HTMLDivElement>(null);
  const face3d = useRef<Face3D | null>(null);
  const [status3d, setStatus3d] = useState<'idle' | 'loading' | 'ready' | 'error'>('idle');
  const videoRef = useRef<HTMLVideoElement>(null);
  const overlayRef = useRef<SVGSVGElement>(null);
  const boxVideo = useRef<HTMLDivElement>(null);
  const [clipNow, setClipNow] = useState<DemoClip | null>(null);

  const draw = () => {
    const scene = sceneAt(ex, clock.get(), plan);
    if (mode === 'video') {
      const clip = clipFor(ex.id, scene.step?.id) ?? null;
      if (clip !== clipNow) setClipNow(clip);
      if (clip && videoRef.current && overlayRef.current) {
        syncVideo(videoRef.current, clip, scene, clock.running, clock.speed);
        overlayRef.current.innerHTML = clipOverlay(clip, scene, clipFlip(clip, view.affectedSide, view.mirror));
        return;
      }
    }
    if ((mode === '2d' || (mode === 'video' && !clipFor(ex.id, scene.step?.id))) && svgRef.current) {
      const r = render2D(scene, { ...view, loupe }, uid);
      svgRef.current.setAttribute('viewBox', r.viewBox);
      svgRef.current.innerHTML = r.svg;
      const lp = loupeRef.current;
      if (lp) {
        // The whole loupe card is hidden when there is nothing to magnify (expressions, massage, breathing).
        const box = lp.parentElement as HTMLElement;
        if (r.loupe && loupe) {
          box.style.display = '';
          lp.setAttribute('viewBox', `${r.loupe.x - r.loupe.r} ${r.loupe.y - r.loupe.r} ${r.loupe.r * 2} ${r.loupe.r * 2}`);
          if (!lp.firstChild) lp.innerHTML = `<use href="#${uid}-scene"/>`;
        } else box.style.display = 'none';
      }
    } else if (mode === '3d' && face3d.current?.ready) {
      face3d.current.update(scene, view);
      (window as unknown as { __fsrPenetration?: number }).__fsrPenetration = face3d.current.lastPenetration;
      if (import.meta.env.DEV) (window as unknown as { __fsrDebug?: unknown }).__fsrDebug = face3d.current.debug();
    }
  };

  // 3D avatar: loaded lazily (three.js + model) the first time it is shown.
  useEffect(() => {
    if (mode !== '3d' || !box3d.current) return;
    let cancelled = false;
    setStatus3d('loading');
    (async () => {
      try {
        const { Face3D } = await import('./face3d');
        if (cancelled || !box3d.current) return;
        const f = new Face3D(box3d.current);
        face3d.current = f;
        await f.load(new URL('./', document.baseURI).href);
        if (cancelled) return;
        setStatus3d('ready');
        draw();
      } catch (e) {
        console.error(e);
        if (!cancelled) {
          setStatus3d('error');
          onFail3D?.();
        }
      }
    })();
    return () => {
      cancelled = true;
      // A failing 3D cleanup must never block leaving the screen (it once left the app stuck on the exercise).
      try {
        face3d.current?.dispose();
      } catch (e) {
        console.error(e);
      }
      face3d.current = null;
    };
  }, [mode]);

  // Draw after every render (pause/seek/settings) and continuously while playing.
  useEffect(() => {
    draw();
    if (!clock.running) return;
    let id = 0;
    const tick = () => {
      draw();
      id = requestAnimationFrame(tick);
    };
    id = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(id);
  });

  if (mode === 'video') {
    const clip = clipNow ?? clipFor(ex.id, sceneAt(ex, clock.get(), plan).step?.id) ?? null;
    return (
      <div class={`fsr-stage mode-video ${clip ? '' : 'no-clip'}`} style={clip ? { background: clip.background } : undefined}>
        {clip ? (
          <div ref={boxVideo} class="fsr-video">
            <video
              ref={videoRef}
              key={clip.id}
              src={clipUrl(clip)}
              poster={clipUrl(clip, 'hold.jpg')}
              muted
              playsInline
              preload="auto"
              style={{ transform: clipFlip(clip, view.affectedSide, view.mirror) ? 'scaleX(-1)' : undefined }}
              aria-label={`${ex.title} 시연 영상`}
            />
            <svg ref={overlayRef} class="fsr-video-ov" viewBox={`0 0 ${clip.size[0]} ${clip.size[1]}`} aria-hidden="true" />
          </div>
        ) : (
          <>
            <svg ref={svgRef} class="fsr-svg" role="img" aria-label={`${ex.title} 따라하기 그림`} />
            <p class="fsr-hint">이 동작은 아직 영상이 없어 그림으로 보여 드려요</p>
          </>
        )}
      </div>
    );
  }

  return (
    <div class={`fsr-stage mode-${mode}`}>
      {mode === '2d' ? (
        <>
          <svg ref={svgRef} class="fsr-svg" role="img" aria-label={`${ex.title} 따라하기 그림`} />
          {/* The loupe sits on the healthy side, below the HUD, away from the action and the callouts. */}
          <div class={`fsr-loupe ${(view.affectedSide === 'left') === view.mirror ? 'right' : 'left'}`} style={{ display: 'none' }}>
            <header>환측 확대</header>
            <svg ref={loupeRef} />
          </div>
        </>
      ) : (
        <div ref={box3d} class="fsr-3d">
          {status3d === 'loading' && <p class="fsr-msg">3D 얼굴 모델을 불러오는 중…</p>}
          {status3d === 'error' && <p class="fsr-msg">3D 모델을 불러오지 못했습니다. 2D 일러스트로 보세요.</p>}
          {status3d === 'ready' && <p class="fsr-hint">드래그해서 옆에서 볼 수 있어요</p>}
        </div>
      )}
    </div>
  );
}

/** Keep the clip on the exercise clock: play at the matching rate, re-seek on drift, freeze for holds. */
function syncVideo(v: HTMLVideoElement, clip: DemoClip, scene: Scene, running: boolean, speed: number) {
  const { t, rate } = clipTime(clip, scene);
  if (running && rate > 0) {
    const r = rate * speed;
    if (Math.abs(v.playbackRate - r) > 0.01) v.playbackRate = r;
    if (Math.abs(v.currentTime - t) > 0.15 * Math.max(1, r)) v.currentTime = t;
    if (v.paused) void v.play().catch(() => undefined);
  } else {
    if (!v.paused) v.pause();
    if (Math.abs(v.currentTime - t) > 0.5 / clip.fps) v.currentTime = t;
  }
}

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => `&${({ '&': 'amp', '<': 'lt', '>': 'gt', '"': 'quot' } as const)[c as '&']};`);

/** Arrow for the stretching hand, lock marks for the fixing fingers, and the step caption (SVG in clip pixels). */
function clipOverlay(clip: DemoClip, scene: Scene, flip: boolean): string {
  const [W, H] = clip.size;
  const px = (p: [number, number]): [number, number] => [(flip ? 1 - p[0] : p[0]) * W, p[1] * H];
  const uy = clip.unit[1] * H;
  const ph = scene.phase.key;
  const onSkin = !scene.done && (ph !== 'prepare' || scene.rep > 1 || scene.phaseT * scene.phase.dur > clip.segment * 0.8);
  const out: string[] = [];
  const fixed = clip.contacts.filter((c) => c.fixed);
  const moving = clip.contacts.filter((c) => !c.fixed);
  if (onSkin && ph !== 'rest') {
    for (const c of fixed) {
      const [x, y] = px(c.from);
      out.push(
        `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><circle r="15" fill="none" stroke="#fff" stroke-width="5"/><circle r="15" fill="none" stroke="${HAND_COLOR.A}" stroke-width="3"/>` +
          `<rect x="-5" y="-2" width="10" height="8" rx="1.5" fill="${HAND_COLOR.A}" stroke="#fff" stroke-width="1"/><path d="M-3 -2v-3a3 3 0 0 1 6 0v3" fill="none" stroke="${HAND_COLOR.A}" stroke-width="2"/></g>`,
      );
    }
  }
  if (moving.length && !scene.done && (ph === 'prepare' || ph === 'stretch' || ph === 'hold')) {
    // One arrow per stretching hand (both hands move in the up/down steps), a bit longer than its move and never
    // shorter than ~2 face units. A sideways move at eye level: above the fingertips (on the forehead, so it does not
    // hide them); a palm: on the back of the hand; an up/down move: just ahead of the fingertips, pointing on; a
    // diagonal (눈썹주름근): beside its path towards the top of the screen, since the pulling hand lies ahead of it.
    const ux = Math.abs(clip.unit[0]) * W;
    const op = ph === 'hold' ? 0.45 : 1;
    for (const hand of ['A', 'B'] as const) {
      const cs = moving.filter((c) => c.hand === hand);
      if (!cs.length) continue;
      const mean = (k: 'from' | 'to') => px([cs.reduce((s, c) => s + c[k][0], 0) / cs.length, cs.reduce((s, c) => s + c[k][1], 0) / cs.length]);
      const m0 = mean('from');
      const m1 = mean('to');
      const [dx, dy] = [m1[0] - m0[0], m1[1] - m0[1]];
      const len = Math.hypot(dx, dy) || 1;
      const palm = cs.every((c) => c.finger === 'palm');
      let x1: number, y1: number, x2: number, y2: number;
      if (palm || (Math.abs(dx) >= Math.abs(dy) && Math.abs(m0[1] - clip.eye[1] * H) < 1.2 * uy)) {
        const grow = Math.max(0.5, (2.2 * ux) / len - 1);
        const lift = palm ? 0 : 3.2 * uy;
        [x1, y1] = [m0[0] - dx * grow * 0.3, m0[1] - dy * grow * 0.3 - lift];
        [x2, y2] = [m1[0] + dx * grow * 0.7, m1[1] + dy * grow * 0.7 - lift];
      } else if (Math.abs(dy) > 1.5 * Math.abs(dx)) {
        const L = Math.max(1.5 * len, 2.2 * ux);
        [x1, y1] = [m1[0] + (dx / len) * 0.6 * ux, m1[1] + (dy / len) * 0.6 * ux];
        [x2, y2] = [x1 + (dx / len) * L, y1 + (dy / len) * L];
      } else {
        const grow = Math.max(0.5, (2.2 * ux) / len - 1);
        const s = dx / len > 0 ? 1 : -1; // the perpendicular that points up the screen
        const [nx, ny] = [(dy / len) * s, (-dx / len) * s];
        [x1, y1] = [m0[0] - dx * grow * 0.3 + nx * 2.2 * ux, m0[1] - dy * grow * 0.3 + ny * 2.2 * ux];
        [x2, y2] = [m1[0] + dx * grow * 0.7 + nx * 2.2 * ux, m1[1] + dy * grow * 0.7 + ny * 2.2 * ux];
      }
      const ang = Math.atan2(y2 - y1, x2 - x1);
      const head = (s: number) =>
        `${(x2 - s * Math.cos(ang - 0.5)).toFixed(1)},${(y2 - s * Math.sin(ang - 0.5)).toFixed(1)} ${x2.toFixed(1)},${y2.toFixed(1)} ${(x2 - s * Math.cos(ang + 0.5)).toFixed(1)},${(y2 - s * Math.sin(ang + 0.5)).toFixed(1)}`;
      out.push(
        `<g opacity="${op}" stroke-linecap="round" stroke-linejoin="round" fill="none">` +
          `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#fff" stroke-width="13"/><polyline points="${head(24)}" stroke="#fff" stroke-width="13"/>` +
          `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="${HAND_COLOR[hand]}" stroke-width="7"/><polyline points="${head(24)}" stroke="${HAND_COLOR[hand]}" stroke-width="7"/></g>`,
      );
    }
  }
  const step = scene.step;
  if (step) {
    // The phase is in the HUD chip above; the caption names the step (short enough to clear the countdown).
    const text = scene.done ? '끝' : step.short;
    const y = H - 26;
    out.push(
      `<g font-family="inherit" text-anchor="middle"><rect x="${W * 0.2}" y="${y - 25}" width="${W * 0.6}" height="38" rx="19" fill="rgba(20,28,40,0.72)"/>` +
        `<text x="${W / 2}" y="${y}" font-size="21" font-weight="700" fill="#fff">${esc(text)}</text></g>`,
    );
  }
  return out.join('');
}

/** Static frame for lists and review sheets. */
export function RehabStill({ ex, t, view, opt }: { ex: Exercise; t: number; view: View2D; opt?: MotionOptions }) {
  const [uid] = useState(() => `fst${++uidSeq}`);
  const plan = planFor(ex, opt);
  const r = render2D(sceneAt(ex, Math.min(t, plan.total), plan), view, uid);
  return <svg class="fsr-svg" viewBox={r.viewBox} dangerouslySetInnerHTML={{ __html: r.svg }} role="img" aria-label={`${ex.title} 그림`} />;
}

/** Time of the first "hold" of a step (for thumbnails). */
export function holdTime(plan: Plan, step = 0): number {
  const b = plan.blocks.find(
    (x) => x.step === step && (x.phase.key === 'hold' || x.phase.key === 'stroke' || x.phase.key === 'inhale' || x.phase.key === 'show'),
  );
  return b ? b.start + Math.min(1, b.phase.dur / 2) : 0;
}
